20	/// One row of the vendor table: the class, the endpoint hosts that belong to it (the host equals
21	/// one or ends with `.` + one), the engine whose runs belong to it (agy, muse, claude), the Codex
22	/// built-in provider it stands for, and the CLOSED list of the published model names it may send.
23	#[derive(Debug)]
24	pub(crate) struct Vendor {
25	    pub class: &'static str,
26	    pub hosts: &'static [&'static str],
27	    pub engine: &'static str,
28	    pub builtin: &'static str,
29	    pub models: &'static [&'static str],
30	}
