383	/// `Get-TelemetryPurpose`: one of [`PURPOSES`], `none` without one, else `other`.
384	pub fn purpose_class(purpose: &str) -> String {
385	    let p = purpose.trim();
386	    if p.is_empty() {
387	        "none".into()
388	    } else if PURPOSES.contains(&p) {
389	        p.into()
390	    } else {
391	        "other".into()
392	    }
393	}
