528	/// `Find-TelemetryRosterEntry`: the roster entry a coordinator's provider LABEL names (ordinal);
529	/// of several, the one of the identity's engine, then the one of its model. Returns the entry's
530	/// index into `roster.entries`.
531	fn find_roster_entry(roster: &Roster, provider: &str, model: &str, engine: &str) -> Option<usize> {
532	    if !roster.exists {
533	        return None;
534	    }
535	    let mut hits: Vec<usize> = roster
536	        .entries
537	        .iter()
538	        .enumerate()
539	        .filter(|(_, e)| e.provider == provider)
540	        .map(|(i, _)| i)
541	        .collect();
542	    if hits.is_empty() {
543	        return None;
544	    }
545	    if !engine.is_empty() {
546	        let by_engine: Vec<usize> = hits
547	            .iter()
548	            .copied()
549	            .filter(|i| {
550	                let e = &roster.entries[*i].engine;
551	                (if e.is_empty() { "codex" } else { e.as_str() }) == engine
552	            })
553	            .collect();
554	        if !by_engine.is_empty() {
555	            hits = by_engine;
556	        }
557	    }
558	    if !model.is_empty() {
559	        if let Some(i) = hits
560	            .iter()
561	            .copied()
562	            .find(|i| roster.entries[*i].model == model)
563	        {
564	            return Some(i);
565	        }
566	    }
567	    hits.first().copied()
568	}
