619	/// `Get-TelemetryJudgeClass`: THE classifier of a COORDINATOR identity (its own code path - a
620	/// coordinator record has no endpoint). The provider NAME decides: `openai` (any case) -> openai;
621	/// `anthropic` (any case) -> anthropic; a LABEL of the reviewer roster -> the class of that entry's
622	/// endpoint; any other name -> the row of the engine the identity names, else other. Without a
623	/// provider: the claude engine or the host `claude-code` -> anthropic, else other (the host is a
624	/// hint, read only then). The model through the same closed lists (`other` outside its vendor's
625	/// list, without a model or without a vendor). Returns `(provider class, model)`.
626	pub(crate) fn judge_class(
627	    c: &CoordinatorView,
628	    roster: Option<&Roster>,
629	    config: Option<&CodexConfig>,
630	) -> (String, String) {
631	    let p = c.provider.trim();
632	    let m = c.model.trim();
633	    let vendor = if !p.is_empty() {
634	        if p.eq_ignore_ascii_case("openai") {
635	            vendor_of_class("openai")
636	        } else if p.eq_ignore_ascii_case("anthropic") {
637	            vendor_of_class("anthropic")
638	        } else {
639	            match roster.and_then(|r| find_roster_entry(r, p, m, &c.engine).map(|i| (r, i))) {
640	                Some((r, i)) => roster_vendor(r, i, config),
641	                None => vendor_of_engine(&c.engine),
642	            }
643	        }
644	    } else if c.engine == "claude" || c.host == "claude-code" {
645	        vendor_of_class("anthropic")
646	    } else {
647	        None
648	    };
649	    let mut model = "other".to_string();
650	    if vendor.is_some() && !m.is_empty() {
651	        model = model_token(vendor, m);
652	        if model == "unknown" {
653	            model = "other".into();
654	        }
655	    }
656	    (
657	        vendor.map(|v| v.class).unwrap_or("other").to_string(),
658	        model,
659	    )
660	}
