662	/// `Test-TelemetryCoordinatorNamed`: whether a ledger entry's `coordinator` names anyone - a
663	/// provider, an unresolved `#n` or a host hint other than `unknown`. A record that names nothing
664	/// is an ABSENT judge (unknown), not an unrecognised one (other).
665	pub(crate) fn coordinator_named(c: Option<&Coordinator>) -> bool {
666	    let Some(c) = c else { return false };
667	    c.provider.as_deref().is_some_and(|p| !p.is_empty())
668	        || c.unresolved.as_deref().is_some_and(|u| !u.is_empty())
669	        || (!c.host.is_empty() && c.host != "unknown")
