714	/// `Resolve-TelemetryJudge`: the judge of a rating event, resolved AT RATING TIME - `actor` when
715	/// given ([`rating_actor`]), else the ledger entry's own `coordinator` when it names anyone (source
716	/// `consult_coordinator`), else `{other, other, unknown}`. `roster`: the reviewer roster (read here
717	/// when a label needs it and none is given).
718	pub fn resolve_judge(entry: &LedgerEntry, actor: Option<&Judge>, roster: Option<&Roster>) -> Judge {
719	    if let Some(a) = actor {
720	        return a.clone();
721	    }
722	    let c = entry.coordinator.as_ref();
723	    if !coordinator_named(c) {
724	        return Judge::unknown();
725	    }
726	    let view = CoordinatorView::of(c.expect("named implies present"));
727	    let owned;
728	    let roster = match roster {
729	        Some(r) => Some(r),
730	        None => {
731	            let p = view.provider.as_str();
732	            if !p.is_empty()
733	                && !p.eq_ignore_ascii_case("openai")
734	                && !p.eq_ignore_ascii_case("anthropic")
735	            {
736	                owned = crate::providers::read_reviewer_roster().ok();
737	                owned.as_ref()
738	            } else {
739	                None
740	            }
741	        }
742	    };
743	    let (provider, model) = judge_class(&view, roster, None);
744	    Judge {
745	        provider,
746	        model,
747	        source: "consult_coordinator".into(),
748	    }
749	}
