751	/// `ConvertTo-TelemetryJudge`: the `judge` object through its own allowlist - `source` one of
752	/// [`JUDGE_SOURCES`] (else unknown), `provider` a class of the table (else other), `model` an
753	/// entry of THAT class's list exactly (else other); an unknown source is always other / other.
754	pub fn closed_judge(provider: &str, model: &str, source: &str) -> Judge {
755	    let source = if JUDGE_SOURCES.contains(&source) {
756	        source
757	    } else {
758	        "unknown"
759	    };
760	    let vendor = if source != "unknown" && !provider.is_empty() {
761	        vendor_of_class(provider)
762	    } else {
763	        None
764	    };
765	    let model = match vendor {
766	        Some(v) if !model.is_empty() && v.models.contains(&model) => model,
767	        Some(v) if v.class == OPENROUTER.class && openrouter_model_token(model) == model => model,
768	        _ => "other",
769	    };
770	    Judge {
771	        provider: vendor.map(|v| v.class).unwrap_or("other").to_string(),
772	        model: model.to_string(),
773	        source: source.to_string(),
774	    }
775	}
