807	/// A version of this client as an event carries it (`app_version`, `bridge_version`): three
808	/// numbers and an optional pre-release tag of letters, digits, dots and dashes.
809	fn is_version(v: &str) -> bool {
810	    let (core, pre) = match v.split_once('-') {
811	        Some((c, p)) => (c, Some(p)),
812	        None => (v, None),
813	    };
814	    let parts: Vec<&str> = core.split('.').collect();
815	    parts.len() == 3
816	        && parts
817	            .iter()
818	            .all(|p| !p.is_empty() && p.len() <= 6 && p.chars().all(|c| c.is_ascii_digit()))
819	        && pre.is_none_or(|p| {
820	            !p.is_empty()
821	                && p.len() <= 32
822	                && p.chars()
823	                    .all(|c| c.is_ascii_alphanumeric() || c == '.' || c == '-')
824	        })
825	}
