854	fn close_event(v: &Value) -> Option<Value> {
855	    use serde_json::{json, Map};
856	    let o = v.as_object()?;
857	    if o.get("app_id")?.as_str()? != "c3" {
858	        return None;
859	    }
860	    let instance_id = o.get("instance_id")?.as_str()?;
861	    if !is_instance_id(instance_id) {
862	        return None;
863	    }
864	    let client_time = chrono::DateTime::parse_from_rfc3339(o.get("client_time")?.as_str()?)
865	        .ok()?
866	        .with_timezone(&chrono::Utc)
867	        .format("%Y-%m-%dT%H:%M:%SZ")
868	        .to_string();
869	    let event_type = o.get("event_type")?.as_str()?;
870	    if event_type != "consultation" && event_type != "rating" {
871	        return None;
872	    }
873	    let empty = Map::new();
874	    let d = o
875	        .get("details")
876	        .and_then(|d| d.as_object())
877	        .unwrap_or(&empty);
878	    let text = |m: &Map<String, Value>, k: &str| -> String {
879	        m.get(k)
880	            .and_then(|x| x.as_str())
881	            .unwrap_or("")
882	            .trim()
883	            .to_string()
884	    };
885	    let engine = text(d, "engine");
886	    let engine = if ENGINES.contains(&engine.as_str()) {
887	        engine
888	    } else {
889	        "other".to_string()
890	    };
891	    // the provider: a CLASS of the table as it stands, else other (a label is never resolved here)
892	    let vendor = vendor_of_class(&text(d, "provider"));
893	    let raw_model = text(d, "model");
894	    let model = if raw_model.is_empty() || raw_model == "unknown" {
895	        "unknown".to_string()
896	    } else {
897	        match model_token(vendor, &raw_model).as_str() {
898	            "unknown" => "other".to_string(),
899	            m => m.to_string(),
900	        }
901	    };
902	    let provider = vendor.map(|v| v.class).unwrap_or("other").to_string();
903	    let raw_purpose = text(d, "purpose");
904	    let purpose = if raw_purpose == "none" {
905	        raw_purpose
906	    } else {
907	        purpose_class(&raw_purpose)
908	    };
909	    let os = closed_os(&text(o, "os"));
910	    let runtime = text(o, "runtime");
911	    let runtime = match runtime.strip_prefix("rust ") {
912	        Some(ver) if is_version(ver) => runtime.clone(),
913	        _ => "other".to_string(),
914	    };
915	    let app_version = text(o, "app_version");
916	    let app_version = if is_version(&app_version) {
917	        app_version
918	    } else {
919	        "unknown".to_string()
920	    };
921	    let consult_ref = Some(text(d, "consult_ref").to_ascii_lowercase()).filter(|r| is_guid(r));
922	    let mut details = Map::new();
923	    details.insert("engine".into(), json!(engine));
924	    details.insert("provider".into(), json!(provider));
925	    details.insert("model".into(), json!(model));
926	    details.insert("purpose".into(), json!(purpose));
927	    let (severity, title) = if event_type == "consultation" {
928	        let raw = text(d, "outcome");
929	        let outcome = match raw.as_str() {
930	            "usable" | "usable-after-continuation" => raw.clone(),
931	            _ => match raw.strip_prefix("failed:") {
932	                Some(c) if FAILURE_CLASSES.contains(&c) => raw.clone(),
933	                _ => "failed:unknown".to_string(),
934	            },
935	        };
936	        let severity = if outcome.starts_with("usable") {
937	            "info"
938	        } else if ["failed:auth", "failed:quota", "failed:operator"].contains(&outcome.as_str()) {
939	            "warning"
940	        } else {
941	            "error"
942	        };
943	        let num = |k: &str| d.get(k).and_then(|x| x.as_i64()).unwrap_or(0);
944	        let small = |k: &str, dflt: u64| {
945	            d.get(k)
946	                .and_then(|x| x.as_u64())
947	                .filter(|n| *n <= u32::MAX as u64)
948	                .unwrap_or(dflt)
949	        };
950	        let flag = |k: &str| d.get(k).and_then(|x| x.as_bool()).unwrap_or(false);
951	        let wall = d
952	            .get("wall_seconds")
953	            .and_then(|x| x.as_f64())
954	            .filter(|w| w.is_finite() && *w >= 0.0)
955	            .unwrap_or(0.0);
956	        details.insert("outcome".into(), json!(outcome));
957	        details.insert("wall_seconds".into(), json!(wall));
958	        details.insert("tokens_in".into(), json!(num("tokens_in")));
959	        details.insert("tokens_out".into(), json!(num("tokens_out")));
960	        details.insert("findings".into(), json!(num("findings")));
961	        details.insert("structured".into(), json!(flag("structured")));
962	        details.insert("format_retry".into(), json!(flag("format_retry")));
963	        details.insert("panel_size".into(), json!(small("panel_size", 1)));
964	        details.insert("peers_used".into(), json!(small("peers_used", 0)));
965	        details.insert("os".into(), json!(closed_os(&text(d, "os"))));
966	        let druntime = text(d, "runtime");
967	        details.insert(
968	            "runtime".into(),
969	            json!(match druntime.strip_prefix("rust ") {
970	                Some(ver) if is_version(ver) => druntime.clone(),
971	                _ => "other".to_string(),
972	            }),
973	        );
974	        let topic = text(d, "topic_tag");
975	        if crate::telemetry::event::TOPIC_VOCAB.contains(&topic.as_str()) {
976	            details.insert("topic_tag".into(), json!(topic));
977	        }
978	        let useful = text(d, "useful");
979	        if ["yes", "partly", "no"].contains(&useful.as_str()) {
980	            details.insert("useful".into(), json!(useful));
981	        }
982	        for k in ["verified", "rejected"] {
983	            if let Some(n) = d.get(k).and_then(|x| x.as_i64()) {
984	                details.insert(k.into(), json!(n));
985	            }
986	        }
987	        if let Some(r) = &consult_ref {
988	            details.insert("consult_ref".into(), json!(r));
989	        }
990	        (severity, purpose.clone())
991	    } else {
992	        let mark = text(d, "mark");
993	        let mark = if ["yes", "partly", "no"].contains(&mark.as_str()) {
994	            mark
995	        } else {
996	            "other".to_string()
997	        };
998	        let bridge = text(d, "bridge_version");
999	        let bridge = if is_version(&bridge) {
1000	            bridge
1001	        } else {
1002	            app_version.clone()
1003	        };
1004	        let judge = match d.get("judge").and_then(|j| j.as_object()) {
1005	            Some(j) => closed_judge(&text(j, "provider"), &text(j, "model"), &text(j, "source")),
1006	            None => Judge::unknown(),
1007	        };
1008	        details.insert("mark".into(), json!(mark));
1009	        details.insert(
1010	            "age_days".into(),
1011	            json!(d
1012	                .get("age_days")
1013	                .and_then(|x| x.as_i64())
1014	                .filter(|n| *n >= 0)
1015	                .unwrap_or(0)),
1016	        );
1017	        details.insert("bridge_version".into(), json!(bridge));
1018	        details.insert("os".into(), json!(closed_os(&text(d, "os"))));
1019	        details.insert("ps_version".into(), json!("unknown"));
1020	        details.insert("judge".into(), judge.to_value());
1021	        if let Some(n) = d
1022	            .get("rating_rev")
1023	            .and_then(|x| x.as_i64())
1024	            .filter(|n| *n >= 1)
1025	        {
1026	            details.insert("rating_rev".into(), json!(n));
1027	        }
1028	        if let Some(r) = &consult_ref {
1029	            details.insert("consult_ref".into(), json!(r));
1030	        }
1031	        ("info", mark)
1032	    };
1033	    let mut out = Map::new();
1034	    out.insert("app_id".into(), json!("c3"));
1035	    out.insert("app_version".into(), json!(app_version));
1036	    out.insert("instance_id".into(), json!(instance_id));
1037	    out.insert("event_type".into(), json!(event_type));
1038	    out.insert("severity".into(), json!(severity));
1039	    out.insert("title".into(), json!(title));
1040	    out.insert("details".into(), Value::Object(details));
1041	    out.insert("tags".into(), json!([provider, model]));
1042	    out.insert("client_time".into(), json!(client_time));
1043	    out.insert("os".into(), json!(os));
1044	    out.insert("runtime".into(), json!(runtime));
1045	    Some(Value::Object(out))
1046	}
